import { createRouter as createTanStackRouter } from '@tanstack/react-router'
import { routeTree } from './routeTree.gen'

/**
 * The router is created from the generated route tree.
 * `routeTree.gen.ts` is generated by `vite dev` / `vite build` — it is
 * gitignored and must never be hand-edited.
 *
 * TanStack Start 1.0 expects this module to export `getRouter`.
 */
export function getRouter() {
  const router = createTanStackRouter({
    routeTree,
    defaultPreload: 'intent',
    scrollRestoration: true,
  })
  return router
}

/** Alias — some TanStack docs/examples call it `createRouter`. */
export const createRouter = getRouter

declare module '@tanstack/react-router' {
  interface Register {
    router: ReturnType<typeof getRouter>
  }
}
